const escape = value => String(value ?? '').replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const SHOP_STATUSES=['Not started','Ready','In progress','Blocked','Complete'];
export function shopBoard(parts, dateLabel) {
 return `<div class="shop-board">${SHOP_STATUSES.map((status,index)=>{const rows=parts.filter(p=>p.status===status).sort((a,b)=>(a.priority==='High'?-1:0)-(b.priority==='High'?-1:0)||(a.due||'9999').localeCompare(b.due||'9999'));return `<section class="shop-lane lane-${index}"><h3>${status}<span>${rows.length}</span></h3><div class="shop-lane-cards">${rows.length?rows.map(p=>`<article class="shop-card"><div class="shop-card-top"><span>${escape(p.number||'No part number')}</span>${p.priority==='High'?'<strong>HIGH PRIORITY</strong>':''}</div><button class="part-name" data-edit="${escape(p.id)}">${escape(p.name)}</button><div class="shop-card-meta"><strong>${escape(p.owner||'Unassigned')}</strong><span>Qty ${p.quantity} · ${escape(p.subsystem||'No subsystem')}</span><span>${escape(p.process||'No process assigned')}</span><span>Due ${escape(dateLabel(p.due))}</span></div>${p.notes?`<p class="shop-note">${escape(p.notes)}</p>`:''}<label class="shop-status-label">Update status<select data-status="${escape(p.id)}" aria-label="Status for ${escape(p.name)}">${SHOP_STATUSES.map(s=>`<option ${s===p.status?'selected':''}>${s}</option>`).join('')}</select></label>${['Not started','Ready','In progress'].includes(status)?`<button class="shop-action" data-advance="${escape(p.id)}" data-next="${status==='In progress'?'Complete':'In progress'}">${status==='In progress'?'✓ Mark complete':'▶ Start work'}</button>`:`<button class="shop-details" data-edit="${escape(p.id)}">${status==='Blocked'?'Review blocker':'View details'}</button>`}</article>`).join(''):'<p class="lane-empty">No parts in this stage</p>'}</div></section>`;}).join('')}</div>`;
}
